				call = 0;
				Trace("enter", state, p, entries.Count, text, "");
				Dispatch:
				switch (state)
				{
					case 0: goto Return;
					case 1: goto Accept;
					case 2:   expected = null; goto Fail;
					case 3: goto S3;
